package com.sharehope.gallery.model;import jakarta.persistence.*;import lombok.*;import java.time.OffsetDateTime;import java.util.UUID;@Entity @Table(name="gallery_items")@Getter@Setter@Builder@NoArgsConstructor@AllArgsConstructor public class GalleryItem{@Id private UUID id;@Column(name="image_url",nullable=false,columnDefinition="text")private String imageUrl;@Column(nullable=false,length=200)private String title;@Column(name="alt_text",nullable=false,length=300)private String altText;@Column(name="display_order",nullable=false)private Integer displayOrder;@Column(nullable=false)private Boolean published;@Column(name="created_at",nullable=false)private OffsetDateTime createdAt;@PrePersist void create(){if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=OffsetDateTime.now();if(displayOrder==null)displayOrder=0;if(published==null)published=true;}}
